-- name: CreatePlanner :exec
-- The id is generated by the API so the revision's shape-only tree can be
-- built before any node row is inserted.
INSERT INTO planners (id, revision_id, kind, label, description, icons, exchange_string, settings)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8);

-- name: ListPlannersByRevision :many
SELECT * FROM planners WHERE revision_id = $1;
